---
- name: Converge
  hosts: all
  gather_facts: true
  tasks:
    - name: Create the directories for nginx configuration
      ansible.builtin.file:
        path: "{{ item }}"
        state: directory
        mode: "0755"
      loop:
        - /tmp/molecule_test/etc/nginx
        - /tmp/molecule_test/etc/nginx/sites-available
        - /tmp/molecule_test/etc/nginx/sites-enabled
        - /tmp/molecule_test/etc/nginx/conf.d
        - /tmp/molecule_test/var/log/nginx
        - /tmp/molecule_test/etc/yum.repos.d
        - /tmp/molecule_test/var/run
        - /tmp/molecule_test/tmp/site1
        - /tmp/molecule_test/tmp/site2

    - name: Create nginx configuration files
      ansible.builtin.copy:
        content: |
          # Managed by Ansible
          {% if ansible_facts['os_family'] == 'RedHat' %} 
          user              nginx;
          {% endif %}
          {% if ansible_facts['os_family'] == 'Debian' %} 
          user              www-data;
          {% endif %}

          worker_processes  {{ ansible_facts['processor_count'] }};
          pid        /var/run/nginx.pid;

          events {
              worker_connections  512;
          }

          http {
                  ssl_protocols TLSv1.2 TLSv1.3;
                  include /etc/nginx/mime.types;
                  default_type application/octet-stream;

                  access_log /var/log/nginx/access.log;
                  error_log /var/log/nginx/error.log;

                  sendfile  on;
                  tcp_nopush  on;
                  tcp_nodelay  on;
                  keepalive_timeout  65;

                  gzip on;
                  gzip_disable "msie6";

                  include /etc/nginx/conf.d/*.conf;
                  include /etc/nginx/sites-enabled/*;
          }
        dest: "/tmp/molecule_test/etc/nginx/nginx.conf"
        mode: "0644"

    - name: Create default.conf file
      ansible.builtin.copy:
        content: "# Managed by Ansible"
        dest: "/tmp/molecule_test/etc/nginx/conf.d/default.conf"
        mode: "0644"

    - name: Create default site configuration
      ansible.builtin.copy:
        content: "# Managed by Ansible"
        dest: "/tmp/molecule_test/etc/nginx/sites-available/default"
        mode: "0644"

    - name: Create symbolic link for default site
      ansible.builtin.file:
        src: "/tmp/molecule_test/etc/nginx/sites-available/default"
        dest: "/tmp/molecule_test/etc/nginx/sites-enabled/default"
        state: link

    - name: Create site configurations
      ansible.builtin.copy:
        content: |
          server {
            listen 8080;
            server_name localhost;
            root /tmp/site1;

            location / {
              try_files $uri $uri/ /index.html;
            }

            location /images/ {
              try_files $uri $uri/ /index.html;
            }
          }
        dest: "/tmp/molecule_test/etc/nginx/sites-available/foo"
        mode: "0644"

    - name: Create another site configuration
      ansible.builtin.copy:
        content: |
          server {
            listen 9090;
            server_name ansible;
            root /tmp/site2;

            location / {
              try_files $uri $uri/ /index.html;
            }

            location /images/ {
              try_files $uri $uri/ /index.html;
            }
          }
        dest: "/tmp/molecule_test/etc/nginx/sites-available/bar"
        mode: "0644"

    - name: Create symbolic links for site configurations
      ansible.builtin.file:
        src: "/tmp/molecule_test/etc/nginx/sites-available/{{ item }}"
        dest: "/tmp/molecule_test/etc/nginx/sites-enabled/{{ item }}"
        state: link
      loop:
        - foo
        - bar

    - name: Create EPEL repo file
      ansible.builtin.copy:
        content: |
          [epel]
          name=Extra Packages for Enterprise Linux 6 - $basearch
          baseurl=http://download.fedoraproject.org/pub/epel/6/$basearch
          failovermethod=priority
          enabled=1
          gpgcheck=0
          gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-EPEL-6
        dest: "/tmp/molecule_test/etc/yum.repos.d/epel_ansible.repo"
        mode: "0644"
